-- ========================================================================
-- BEGIN 07_create_table_grade.sql
-- ========================================================================

-- Eligibility determination for an application.
--
-- This is the output of the grading engine: a single outcome plus
-- the validity period of the resulting certificate.

CREATE TABLE grade (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,

    application_id UUID NOT NULL UNIQUE
        REFERENCES application(id) ON DELETE CASCADE,

    outcome TEXT NOT NULL DEFAULT '' CHECK (outcome IN ('eligible', 'ineligible', 'requires-clarification', '')),
    redirect_to TEXT NOT NULL DEFAULT '' CHECK (redirect_to IN ('', 'FW8', 'age-exemption', 'low-income-scheme', 'hc1', 'hc2')),

    result_category TEXT NOT NULL DEFAULT '',
    result_score NUMERIC(5, 2),
    result_notes TEXT NOT NULL DEFAULT '',

    valid_from DATE,
    valid_until DATE,
    validity_years INTEGER NOT NULL DEFAULT 5 CHECK (validity_years BETWEEN 0 AND 10),

    graded_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TRIGGER trigger_grade_updated_at
    BEFORE UPDATE ON grade
    FOR EACH ROW
    EXECUTE FUNCTION set_updated_at();

COMMENT ON TABLE grade IS
    'Computed eligibility determination for an FP92A application.';
COMMENT ON COLUMN grade.id IS
    'Primary key UUID, auto-generated.';
COMMENT ON COLUMN grade.created_at IS
    'Timestamp when the record was created.';
COMMENT ON COLUMN grade.updated_at IS
    'Timestamp when the record was updated most-recently.';
COMMENT ON COLUMN grade.deleted_at IS
    'Timestamp when the record was deleted a.k.a. soft-removed.';
COMMENT ON COLUMN grade.application_id IS
    'Foreign key to the parent application (one grade per application).';
COMMENT ON COLUMN grade.outcome IS
    'Eligibility outcome: eligible, ineligible, or requires-clarification.';
COMMENT ON COLUMN grade.redirect_to IS
    'If ineligible on FP92A, suggested alternative exemption route.';
COMMENT ON COLUMN grade.result_category IS
    'Headline category as a human-readable label.';
COMMENT ON COLUMN grade.result_score IS
    'Numeric score (always 1.0 for eligible, 0.0 otherwise).';
COMMENT ON COLUMN grade.result_notes IS
    'Free-text rationale or summary attached to the grade.';
COMMENT ON COLUMN grade.valid_from IS
    'Date the certificate would become valid (typically completed_date).';
COMMENT ON COLUMN grade.valid_until IS
    'Date the certificate would expire (typically valid_from + validity_years).';
COMMENT ON COLUMN grade.validity_years IS
    'Number of years the certificate is valid for (NHSBSA default: 5).';
COMMENT ON COLUMN grade.graded_at IS
    'Timestamp the grade was last (re-)computed.';

-- ========================================================================
-- END 07_create_table_grade.sql
-- ========================================================================

-- ========================================================================
-- BEGIN 08_create_table_grade_fired_rule.sql
-- ========================================================================

-- Per-grade record of which scoring rules fired during eligibility evaluation.

CREATE TABLE grade_fired_rule (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,

    grade_id UUID NOT NULL
        REFERENCES grade(id) ON DELETE CASCADE,

    rule_id VARCHAR(64) NOT NULL DEFAULT '',
    category VARCHAR(32) NOT NULL DEFAULT '' CHECK (category IN (
        'eligible-condition',
        'disqualifying',
        'redirect',
        'completeness',
        'renewal',
        ''
    )),
    description TEXT NOT NULL DEFAULT '',
    severity_level VARCHAR(16) NOT NULL DEFAULT '' CHECK (severity_level IN ('info', 'low', 'medium', 'high', '')),
    contributing_condition_code TEXT NOT NULL DEFAULT ''
);

CREATE TRIGGER trigger_grade_fired_rule_updated_at
    BEFORE UPDATE ON grade_fired_rule
    FOR EACH ROW
    EXECUTE FUNCTION set_updated_at();

COMMENT ON TABLE grade_fired_rule IS
    'Audit trail of rules that fired when computing an eligibility grade.';
COMMENT ON COLUMN grade_fired_rule.id IS
    'Primary key UUID, auto-generated.';
COMMENT ON COLUMN grade_fired_rule.created_at IS
    'Timestamp when the record was created.';
COMMENT ON COLUMN grade_fired_rule.updated_at IS
    'Timestamp when the record was updated most-recently.';
COMMENT ON COLUMN grade_fired_rule.deleted_at IS
    'Timestamp when the record was deleted a.k.a. soft-removed.';
COMMENT ON COLUMN grade_fired_rule.grade_id IS
    'Foreign key to the parent grade.';
COMMENT ON COLUMN grade_fired_rule.rule_id IS
    'Stable identifier of the rule that fired.';
COMMENT ON COLUMN grade_fired_rule.category IS
    'Rule category: eligible-condition, disqualifying, redirect, completeness, renewal.';
COMMENT ON COLUMN grade_fired_rule.description IS
    'Human-readable description of why the rule fired.';
COMMENT ON COLUMN grade_fired_rule.severity_level IS
    'Severity level for sorting / display.';
COMMENT ON COLUMN grade_fired_rule.contributing_condition_code IS
    'Optional eligible-condition code the rule was evaluated against.';

-- ========================================================================
-- END 08_create_table_grade_fired_rule.sql
-- ========================================================================

-- ========================================================================
-- BEGIN 09_create_table_grade_additional_flag.sql
-- ========================================================================

-- Per-grade record of additional flags raised during eligibility evaluation
-- (educational, advisory, or workflow-routing hints distinct from rules that
-- directly determine the outcome).

CREATE TABLE grade_additional_flag (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,

    grade_id UUID NOT NULL
        REFERENCES grade(id) ON DELETE CASCADE,

    flag_id VARCHAR(64) NOT NULL DEFAULT '',
    category VARCHAR(32) NOT NULL DEFAULT '' CHECK (category IN (
        'completeness',
        'data-quality',
        'workflow',
        'education',
        'safeguarding',
        'pregnancy',
        'age-exemption',
        ''
    )),
    description TEXT NOT NULL DEFAULT '',
    priority VARCHAR(16) NOT NULL DEFAULT '' CHECK (priority IN ('low', 'medium', 'high', ''))
);

CREATE TRIGGER trigger_grade_additional_flag_updated_at
    BEFORE UPDATE ON grade_additional_flag
    FOR EACH ROW
    EXECUTE FUNCTION set_updated_at();

COMMENT ON TABLE grade_additional_flag IS
    'Per-grade advisory flags surfaced to the practitioner.';
COMMENT ON COLUMN grade_additional_flag.id IS
    'Primary key UUID, auto-generated.';
COMMENT ON COLUMN grade_additional_flag.created_at IS
    'Timestamp when the record was created.';
COMMENT ON COLUMN grade_additional_flag.updated_at IS
    'Timestamp when the record was updated most-recently.';
COMMENT ON COLUMN grade_additional_flag.deleted_at IS
    'Timestamp when the record was deleted a.k.a. soft-removed.';
COMMENT ON COLUMN grade_additional_flag.grade_id IS
    'Foreign key to the parent grade.';
COMMENT ON COLUMN grade_additional_flag.flag_id IS
    'Stable identifier of the flag.';
COMMENT ON COLUMN grade_additional_flag.category IS
    'Flag category for grouping in the UI.';
COMMENT ON COLUMN grade_additional_flag.description IS
    'Human-readable description shown to the practitioner.';
COMMENT ON COLUMN grade_additional_flag.priority IS
    'Display priority: low, medium, or high.';

-- ========================================================================
-- END 09_create_table_grade_additional_flag.sql
-- ========================================================================
